mapper.select:
SELECT 
FROM notes n
JOIN users u ON n.author_id = u.user_id
JOIN questions q ON n.question_id = q.question_id

    AND n.question_id = #{param.questionId}
    AND n.author_id = #{param.authorId}

        AND EXISTS (
            SELECT 1 FROM note_tags nt
            JOIN tags t ON nt.tag_id = t.tag_id
            WHERE nt.note_id = n.note_id AND t.name = #{param.tag}
        )




        ORDER BY (n.like_count * 2 + n.comment_count * 3 + n.collect_count) DESC, n.note_id DESC


        ORDER BY n.created_at DESC, n.note_id DESC


LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM notes n

    AND n.question_id = #{param.questionId}
    AND n.author_id = #{param.authorId}

        AND EXISTS (
            SELECT 1 FROM note_tags nt
            JOIN tags t ON nt.tag_id = t.tag_id
            WHERE nt.note_id = n.note_id AND t.name = #{param.tag}
        )

mapper.update:
UPDATE notes
SET like_count = GREATEST(CAST(like_count AS SIGNED) + #{delta}, 0), updated_at = CURRENT_TIMESTAMP
WHERE note_id = #{noteId}

UPDATE notes
SET comment_count = GREATEST(CAST(comment_count AS SIGNED) + #{delta}, 0), updated_at = CURRENT_TIMESTAMP
WHERE note_id = #{noteId}

UPDATE notes
SET collect_count = GREATEST(CAST(collect_count AS SIGNED) + #{delta}, 0), updated_at = CURRENT_TIMESTAMP
WHERE note_id = #{noteId}

